// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, checkSchema } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createBulkArchiveJob,
    getBulkArchiveJob,
    deleteLink,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, headers, "testbot-bulk-archive-col");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("testbot-bulk-archive-col");
    expect(Number(getResponseValue(collectionsPostResponse, "response.id")), 'id').toBeGreaterThan(0);

    const linksPostResponse = await createLink(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id"),
        "testbot-bulk-archive-link",
        "https://example.com/testbot-bulk-archive"
    );
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot-bulk-archive-link");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/testbot-bulk-archive");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(Number(getResponseValue(linksPostResponse, "response.id")), 'id').toBeGreaterThan(0);

    const bulkArchivePostResponse = await createBulkArchiveJob(client, headers, [
        getResponseValue(linksPostResponse, "response.id"),
    ]);
    expect(getResponseValue(bulkArchivePostResponse, "response.jobId"), 'jobId').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getResponseValue(bulkArchivePostResponse, "response.status"), 'status').toBe("queued");

    const bulkArchiveBulkArchiveGetResponse = await getBulkArchiveJob(
        client,
        headers,
        getResponseValue(bulkArchivePostResponse, "response.jobId")
    );
    expect(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.id"), 'id').toBe(getResponseValue(bulkArchivePostResponse, "response.jobId"));
    expect(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.status"), 'status').toBe("queued");
    expect(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.totalLinks"), 'totalLinks').toBe(1);
    expect(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.archivedCount"), 'archivedCount').toBe(0);
    expect(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.failedCount"), 'failedCount').toBe(0);
    expect(
        Number.isNaN(Date.parse(String(getResponseValue(bulkArchiveBulkArchiveGetResponse, "response.createdAt")))),
        'createdAt parses as a time'
    ).toBe(false);
    expect(checkSchema(bulkArchiveBulkArchiveGetResponse, '{"response":{"completedAt":null}}'), 'completedAt present and null').toBe(true);

    const linksLinksDeleteResponse = await deleteLink(client, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
